  'key': 'keyDetails',
  'enquiry': 'rawEnquiry'
};

const sectionKeys = new Set(['workorder', 'jobDetails', 'tenant', 'invoicingDetails', 'keyDetails', 'rawEnquiry']);

function parseContent(content) {
  const raw = String(content || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').replace(/ /g, ' ');
  const result = {
    firstName: '',
    lastName: '',
    customerName: '',
    customerJobTitle: '',
    mobileNumber: '',
    phoneNumber: '',
    emailAddress: '',
    address: '',
    streetAddressDescription: '',
    state: '',
    suburb: '',
    postalCode: '',
    country: '',
    quantity: '',
    IdLikeToGetMyProjectUnderway: '',
    howTheyHeardAboutUs: 'Google',
    leadQualifier: 'Good',
    referredBy: '',
    workorder: '',
    jobDetails: '',
    tenant: '',
    invoicingDetails: '',
    keyDetails: '',
    rawEnquiry: ''
  };

  const lines = raw.split('\n');
  let activeSection = '';

  for (const originalLine of lines) {
    const line = String(originalLine || '').trim();
    if (!line) continue;

    const match = line.match(/^([^:]+):[ \t]*([^\n\r]*)$/);
    if (match) {
      const rawLabel = normLabel(match[1]);
      const key = fieldAliases[rawLabel];
      if (key) {
        const value = String(match[2] || '').trim();
        if (sectionKeys.has(key)) {
          result[key] = value;
          activeSection = key;
        } else {
          result[key] = value;
          activeSection = '';
        }
        continue;
      }
    }

    if (activeSection && sectionKeys.has(activeSection)) {
      result[activeSection] = [result[activeSection], line].filter(Boolean).join('\n');
    } else {
      result.rawEnquiry = [result.rawEnquiry, line].filter(Boolean).join('\n');
    }
  }

  if (!result.customerName) result.customerName = regexValue(raw, 'Customer Name');
  if (!result.customerJobTitle) result.customerJobTitle = regexValue(raw, 'Customer Job Title');
  if (!result.mobileNumber) result.mobileNumber = regexValue(raw, 'Mobile Number');
  if (!result.phoneNumber) result.phoneNumber = regexValue(raw, 'Phone Number');
  if (!result.emailAddress) result.emailAddress = regexValue(raw, 'Email Address');
  if (!result.address) result.address = regexValue(raw, 'Street Address') || regexValue(raw, 'Address');
  if (!result.suburb) result.suburb = regexValue(raw, 'Suburb');
  if (!result.postalCode) result.postalCode = regexValue(raw, 'Postal Code');
  if (!result.country) result.country = regexValue(raw, 'Country');

  if (isPlaceholder(result.phoneNumber) || /street address/i.test(result.phoneNumber)) result.phoneNumber = '';
  if (isPlaceholder(result.address) || /street address description/i.test(result.address)) result.address = '';
  if (isPlaceholder(result.postalCode) || /country\s*:|australia/i.test(result.postalCode)) result.postalCode = '';
  if (isPlaceholder(result.state)) result.state = '';
  if (isPlaceholder(result.tenant)) result.tenant = '';
  if (isPlaceholder(result.keyDetails)) result.keyDetails = '';
  if (isPlaceholder(result.invoicingDetails)) result.invoicingDetails = '';

  result.postalCode = cleanPostalCode(result.postalCode);
  result.state = cleanState(result.state);

  if ((!result.firstName && !result.lastName) && result.customerName) {
    const split = splitName(result.customerName);
    result.firstName = split.firstName;
    result.lastName = split.lastName;
  }

  const acronym = jobTitleAcronym(result.customerJobTitle);
  if (acronym && result.lastName && !result.lastName.includes(`(${acronym})`)) {
    result.lastName = `${result.lastName} (${acronym})`;
  }

  if (!result.jobDetails && result.rawEnquiry) {
    result.jobDetails = result.rawEnquiry;
  }

  return result;
}

function formatEnquiry(data) {
  return [
    `Workorder#:\n${data.workorder || ''}`,
    `Job Details:\n${data.jobDetails || ''}`,
    `Tenant:\n${data.tenant || ''}`,
    `Invoice details:\n${data.invoicingDetails || ''}`,
    `Key:\n${data.keyDetails || ''}`
  ].join('\n\n').trim();
}

return items.map((item) => {
  const meta = item.json;
  const parsed = parseContent(meta.content);
  const fileBase = [parsed.firstName, parsed.lastName].filter(Boolean).join('') || 'EmailEnquiryLead';
  return {
    json: {
      messageId: meta.messageId,
      channelId: meta.channelId,
      authorId: meta.authorId,
      authorName: meta.authorName,
      id: meta.messageId,
      Timestamp: meta.postedAt,
      postedAt: meta.postedAt,
      leadType: meta.leadType || 'Email Enquiry Lead',
      leadSourceChannel: meta.leadSourceChannel || '',
      firstName: parsed.firstName,
      lastName: parsed.lastName,
      customerJobTitle: parsed.customerJobTitle,
      jobTitleAcronym: jobTitleAcronym(parsed.customerJobTitle),
      mobileNumber: parsed.mobileNumber,
      phoneNumber: parsed.phoneNumber,
      emailAddress: parsed.emailAddress,
      address: parsed.address,
      state: parsed.state,
      suburb: parsed.suburb,
      postalCode: parsed.postalCode,
      enquiry: formatEnquiry(parsed),
      quantity: parsed.quantity,
      IdLikeToGetMyProjectUnderway: parsed.IdLikeToGetMyProjectUnderway,
      howTheyHeardAboutUs: 'Google',
      leadQualifier: 'Good',
      referredBy: parsed.referredBy || '',
      imageAttachments: meta.imageAttachments,
      fileName: `${fileBase}-${meta.messageId}`
    }
  };
});

const base = $input.first().json;
const imgs = Array.isArray(base.imageAttachments) ? base.imageAttachments : [];
if (!imgs.length) return [];

function safePart(value) {
  return String(value || '').replace(/[^a-zA-Z0-9._-]+/g, '_').replace(/^_+|_+$/g, '') || 'image';
}

return imgs.map((img, index) => ({
  json: {
    messageId: base.messageId,
    image: img,
    imageFetchUrl: String(img?.proxyURL || img?.url || '').trim(),
    uploadName: `${safePart(base.messageId)}-${String(index + 1).padStart(2, '0')}-${safePart(img?.name || 'attachment')}`
  }
}));

const ai = items[0]?.json || {};
const lead = items[1]?.json || {};

function norm(value) {
  return String(value || '').trim().toLowerCase();
}

const stateFullNameMap = {
  'NEW SOUTH WALES': 'NSW',
  'QUEENSLAND': 'QLD',
  'VICTORIA': 'VIC',
  'SOUTH AUSTRALIA': 'SA',
  'WESTERN AUSTRALIA': 'WA',
  'TASMANIA': 'TAS',
  'NORTHERN TERRITORY': 'NT',
  'AUSTRALIAN CAPITAL TERRITORY': 'ACT'
};

function cleanState(value) {
  const raw = String(value || '').trim().toUpperCase();
  if (!raw) return '';
  if (stateFullNameMap[raw]) return stateFullNameMap[raw];
  return /^(NSW|QLD|VIC|SA|WA|TAS|NT|ACT)$/.test(raw) ? raw : '';
}

function cleanPostalCode(value) {
  const raw = String(value || '').trim();
  const match = raw.match(/\b\d{4}\b/);
  return match ? match[0] : '';
}

function stateFromPostcode(pc) {
  const first = String(pc || '').trim()[0];
  return ({'1':'NSW','2':'NSW','3':'VIC','4':'QLD','5':'SA','6':'WA','7':'TAS','8':'NT','0':'NT'})[first] || '';
}

function isBadText(value) {
  const raw = String(value || '').trim();
  const v = norm(value);
  return !v || /:$/.test(raw) || v === 'country: australia' || v === 'street address:' || v === 'street address description:' || v === 'postal code:' || v === 'phone number:' || v.includes('street address') || v.includes('country: australia');
}

function extractJson(raw) {
  if (raw && typeof raw === 'object' && raw.state !== undefined && raw.postalCode !== undefined) {
    return raw;
  }
  if (raw?.message?.content && typeof raw.message.content === 'object') {
    return raw.message.content;
  }
  if (Array.isArray(raw) && raw[0]?.message?.content && typeof raw[0].message.content === 'object') {
    return raw[0].message.content;
  }
  const text = raw?.message?.content || raw?.choices?.[0]?.message?.content || raw?.content || raw?.output_text || '';
  if (!text) return {};
  try {
    return typeof text === 'string' ? JSON.parse(text) : text;
  } catch {
    const match = String(text).match(/\{[\s\S]*\}/);
    if (!match) return {};
    try {
      return JSON.parse(match[0]);
    } catch {
      return {};
    }
  }
}

const enriched = extractJson(ai);
const aiState = cleanState(enriched.state);
const aiPostalCode = cleanPostalCode(enriched.postalCode);
const leadState = cleanState(lead.state);
const leadPostalCode = cleanPostalCode(lead.postalCode);

const finalPostalCode = leadPostalCode || aiPostalCode || '';
const finalState = leadState || aiState || stateFromPostcode(finalPostalCode) || 'QLD';

return [{
  json: {
    ...lead,
    state: finalState,
    postalCode: finalPostalCode,
    phoneNumber: isBadText(lead.phoneNumber) ? '' : String(lead.phoneNumber || '').trim(),
    address: isBadText(lead.address) ? '' : String(lead.address || '').trim()
  }
}];

const item = $input.first().json;

function normalizeQuotes(s) {
  return String(s || '')
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'");
}

function stripControls(s) {
  return s.replace(/[�-  -]/g, ' ');
}

function cleanText(value) {
  if (value === null || value === undefined) return '';
  return stripControls(normalizeQuotes(String(value)))
    .replace(/\\/g, '/')
    .replace(/"/g, "'")
    .replace(/ /g, ' ')
    .replace(/[\t ]+/g, ' ')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function canonical(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const safe = {
  ...item,
  Timestamp: cleanText(item.Timestamp),
  id: cleanText(item.id),
  leadType: item.leadType || 'Email Enquiry Lead',
  leadSourceChannel: item.leadSourceChannel || '',
  firstName: cleanText(item.firstName),
  lastName: cleanText(item.lastName),
  mobileNumber: cleanText(item.mobileNumber),
  phoneNumber: cleanText(item.phoneNumber),
  emailAddress: cleanText(item.emailAddress).toLowerCase(),
  address: cleanText(item.address),
  state: cleanText(item.state),
  suburb: cleanText(item.suburb),
  postalCode: cleanText(item.postalCode),
  enquiry: cleanText(item.enquiry),
  quantity: cleanText(item.quantity),
  IdLikeToGetMyProjectUnderway: cleanText(item.IdLikeToGetMyProjectUnderway),
  howTheyHeardAboutUs: 'Google',
  leadQualifier: 'Good',
  referredBy: cleanText(item.referredBy)
};

const imageKey = Array.isArray(item.imageAttachments)
  ? item.imageAttachments.map((img) => canonical(img?.id || img?.name || img?.url || '')).filter(Boolean).join('|')
  : '';

const leadFingerprint = [
  canonical(safe.leadType),
  canonical(safe.emailAddress),
  canonical(safe.mobileNumber),
  canonical(safe.phoneNumber),
  canonical(safe.address),
  canonical(safe.suburb),
  canonical(safe.postalCode),
  canonical(safe.enquiry).slice(0, 180),
  imageKey
].filter(Boolean).join('|') || safe.id;

return [{ json: { ...safe, leadFingerprint } }];

